class BankAccount {
  constructor(owner, balance) {
    this.owner = owner;
    this._balance = balance;
  }

  get balance() {
    return this._balance;
  }

  deposit(amount) {
    this._balance += amount;
  }

  withdrawal(amount) {
    if (amount <= this._balance) {
      this._balance -= amount;
    } else {
      console.log("Insufficient balance");
    }
  }

  display() {
    console.log(`${this.owner}'s balance: $${this._balance}`);
  }
}

// Create object
